    @model_validator(mode="after")
    def valid(self):
        # No remote schema fetching during either incubation or execution.
        def local(value, depth=0):
            if depth > 32:
                raise ValueError("Method value schema exceeds its depth limit")
            if isinstance(value, dict):
                for key, item in value.items():
                    if key in ("$id", "$anchor", "$dynamicAnchor", "$dynamicRef"):
                        raise ValueError("Method schemas use local JSON pointers only")
                    if key == "$ref":
                        if not isinstance(item, str) or not item.startswith("#/"):
                            raise ValueError(
                                "Method value schemas must be self-contained"
                            )
                        target = self.schema_
                        for segment in item[2:].split("/"):
                            segment = segment.replace("~1", "/").replace("~0", "~")
                            if not isinstance(target, dict) or segment not in target:
                                raise ValueError(
                                    "Method schema reference does not exist"
                                )
                            target = target[segment]
                    local(item, depth + 1)
            elif isinstance(value, list):
                for item in value:
                    local(item, depth + 1)

        local(self.schema_)
        if len(json.dumps(self.schema_, allow_nan=False)) > 64000:
            raise ValueError("Method value schema exceeds its size limit")
        try:
            Draft202012Validator.check_schema(self.schema_)
        except SchemaError as exc:
            raise ValueError("Invalid method value schema") from exc
        if self.required and self.on_missing == "omit":
            raise ValueError("A required value cannot be silently omitted")
        return self


