class Orchestration(Strict):
    kind: Literal["orchestration"]
    instructions: Text
    steps: tuple[MethodStep, ...] = Field(min_length=1, max_length=100)
    exports: dict[Name, Export] = Field(min_length=1, max_length=100)
    max_depth: int = Field(strict=True, ge=1, le=16)
    max_expansions: int = Field(strict=True, ge=1, le=1000)
    max_steps: int = Field(strict=True, ge=1, le=1000)
    max_replans: int = Field(strict=True, ge=0, le=10)

    @model_validator(mode="after")
    def valid(self):
        steps = {s.id: s for s in self.steps}
        if len(steps) != len(self.steps):
            raise ValueError("Duplicate step identity")
        done: set[str] = set()
        visiting: set[str] = set()

        def visit(key: str):
            if key not in steps or key in visiting:
                raise ValueError("Unknown dependency or cyclic method steps")
            if key in done:
                return
            visiting.add(key)
            for dep in steps[key].depends_on:
                visit(dep)
            visiting.remove(key)
            done.add(key)

        for step in self.steps:
            visit(step.id)
            for inp in step.inputs.values():
                if not isinstance(inp.binding, StepValue):
                    continue
                ref = inp.binding
                if (
                    ref.step not in step.depends_on
                    or ref.output not in steps[ref.step].outputs
                ):
                    raise ValueError(
                        "Step input must name a declared dependency output"
                    )
                provided = steps[ref.step].outputs[ref.output]
                if (
                    provided.schema_ != inp.slot.schema_
                    or provided.meaning != inp.slot.meaning
                ):
                    raise ValueError(
                        "A binding cannot perform an implicit business conversion"
                    )
                if inp.slot.required and not provided.required:
                    raise ValueError("Optional output cannot satisfy a required input")
        for ref in self.exports.values():
            if ref.step not in steps or ref.output not in steps[ref.step].outputs:
                raise ValueError("An export must name an actual step output")
            if ref.always_present and (
                not steps[ref.step].always_required
                or not steps[ref.step].outputs[ref.output].required
            ):
                raise ValueError(
                    "Every legal plan must produce an unconditional export"
                )
        return self


