class FormalMethodDefinition(Strict):
    contract: Literal["knowlab/formal-method/v1"]
    capability_declaration: CapabilityDeclaration
    access_requirements: tuple[AccessRequirement, ...] = Field(max_length=100)
    procedure: Annotated[ToolProcedure | Orchestration, Field(discriminator="kind")]
    how_to_validate: tuple[ValidationRule, ...] = Field(min_length=1, max_length=100)
    what_requires_approval: tuple[ApprovalRule, ...] = Field(max_length=100)

